// FUNCTIONS //

/**
* Returns a string containing environment variable for generating pseudorandom numbers.
*
* @private
* @param {Object} obj - configuration object
* @returns {string} environment variable string
*
* @example
* var o = {
*     'prng': 'random/base/uniform',
*     'parameters': [ -10, 10 ]
* };
*
* var s = prngEnvVars( o );
* // returns 'BASE_PRNG=\'uniform\',RAND_MIN=-10,RAND_MAX=10'
*/
function prngEnvVars( obj ) {
	var base;
	var min;
	var max;
	var p;

	p = obj.prng.split( '/' );
	base = p[ p.length-1 ];
	min = obj.parameters[ 0 ];
	max = obj.parameters[ 1 ];
	if ( base === 'uniform' ) {
		if ( isInteger( min ) ) {
			min = min.toString() + '.0';
		}
		if ( isInteger( max ) ) {
			max = max.toString() + '.0';
		}
	} else {
		min = min.toString();
		max = max.toString();
	}
	return [
		'BASE_PRNG=\'' + base + '\'',
		'RAND_MIN=' + min,
		'RAND_MAX=' + max
	].join( ' ' );
}

/**
* Returns an `ALIAS` environment variable string.
*
* @private
* @param {string} alias - package alias
* @returns {string} environment variable string
*
* @example
* var s = aliasEnvVar( 'abs' );
* // returns 'ALIAS=abs'
*
* @example
* var s = aliasEnvVar( 'absf' );
* // returns 'ALIAS=absf'
*/
function aliasEnvVar( alias ) {
	return 'ALIAS=' + alias;
}

/**
* Returns the main export description environment variable.
*
* @private
* @param {string} desc - function description
* @returns {string} environment variable string
*/
function mainDescEnvVar( desc ) {
	return 'MAIN_DESC=\'' + desc + ' for each element in an ndarray.\'';
}

/**
* Returns a string containing example values for a 2x2 array environment variable.
*
* @private
* @param {Array} values - example values
* @returns {string} environment variable string
*
* @example
* var exampleValues = [ 1.9, 4.8, 6.0, 8.1 ];
* var out = jsExampleValues2x2EnvVar( exampleValues );
* // returns "JS_EXAMPLE_VALUES_2X2='[ [ 1.9, 4.8 ], [ 6.0, 8.1 ] ]'"
*
* @example
* var exampleValues = [ { re: 1.9, im: 2.1 }, { re: 4.8, im: 3.2 }, { re: 6.0, im: 1.5 }, { re: 8.1, im: 2.7 } ];
* var out = jsExampleValues2x2EnvVar( exampleValues );
* // returns "JS_EXAMPLE_VALUES_2X2='[ [ { re: 1.9, im: 2.1 }, { re: 4.8, im: 3.2 } ], [ { re: 6.0, im: 1.5 }, { re: 8.1, im: 2.7 } ] ]'"
*/
function jsExampleValues2x2EnvVar( values ) {
	var bottomRow;
	var topRow;
	var matrix;
	var vals;
	var v;
	var i;

	// Check if there are complex values in the array:
	if ( values && values[ 0 ] && isComplexLike( values[ 0 ] ) ) {
		matrix = [];
		for ( i = 0; i < 4; i++ ) {
			v = values[ i ];
			if ( v && isComplexLike( v ) ) {
				matrix.push( '{ re: ' + v.re + ', im: ' + v.im + ' }' );
			} else {
				matrix.push( '{ re: ' + v + ', im: 0 }' );
			}
		}
		topRow = join( slice( matrix, 0, 2 ), ', ' );
		bottomRow = join( slice( matrix, 2, 4 ), ', ' );
		return 'JS_EXAMPLE_VALUES_2X2=\'[ [ ' + topRow + ' ], [ ' + bottomRow + ' ] ]\'';
	}

	// For real values:
	vals = [];
	for ( i = 0; i < 4; i++ ) {
		v = values[ i ];
		vals.push( v.toString() );
	}
	topRow = join( slice( vals, 0, 2 ), ', ' );
	bottomRow = join( slice( vals, 2, 4 ), ', ' );
	return 'JS_EXAMPLE_VALUES_2X2=\'[ [ ' + topRow + ' ], [ ' + bottomRow + ' ] ]\'';
}

/**
* Returns a string containing example results for a 2x2 array environment variable.
*
* @private
* @param {Array} exampleValues - example input values
* @param {Function} fn - function to apply to each value
* @returns {string} environment variable string
*
* @example
* var abs = require( '@stdlib/math/base/special/abs' );
*
* var exampleValues = [ 1.9, -4.8, -6.0, 8.1 ];
* var out = jsExampleResults2x2EnvVar( exampleValues, abs );
* // returns "JS_EXAMPLE_RESULTS_2X2='[ [ 1.9, 4.8 ], [ 6.0, 8.1 ] ]'"
*/
function jsExampleResults2x2EnvVar( exampleValues, fn ) {
	var bottomRow;
	var results;
	var topRow;
	var v;
	var r;
	var i;

	// For complex values:
	if ( exampleValues && exampleValues[ 0 ] && isComplexLike( exampleValues[ 0 ] ) ) { // eslint-disable-line max-len
		results = [];
		for ( i = 0; i < 4; i++ ) {
			v = exampleValues[ i ];
			r = fn( v );
			results.push( r );
		}
		topRow = join( slice( results, 0, 2 ), ', ' );
		bottomRow = join( slice( results, 2, 4 ), ', ' );
		return 'JS_EXAMPLE_RESULTS_2X2=\'[ [ ' + topRow + ' ], [ ' + bottomRow + ' ] ]\'';
	}

	// For real values:
	results = [];
	for ( i = 0; i < 4; i++ ) {
		v = exampleValues[ i ];
		r = fn( v );
		results.push( r );
	}
	topRow = join( slice( results, 0, 2 ), ', ' );
	bottomRow = join( slice( results, 2, 4 ), ', ' );
	return 'JS_EXAMPLE_RESULTS_2X2=\'[ [ ' + topRow + ' ], [ ' + bottomRow + ' ] ]\'';
}

/**
* Returns the assign export description environment variable.
*
* @private
* @param {string} desc - function description
* @returns {string} environment variable string
*/
function assignDescEnvVar( desc ) {
	return 'ASSIGN_DESC=\'' + desc + ' for each element in an ndarray and assigns results to a provided output ndarray.\'';
}

/**
* Returns the input/output dtypes and policies environment variables.
*
* @private
* @param {Object} funcData - function data
* @returns {string} environment variable string
*
* @example
* var funcData = {
*     "input_dtypes": "numeric_and_generic",
*     "output_dtypes": "real_and_generic",
*     "policies": {
*         "output": "real_and_generic",
*         "casting": "none"
*     }
* };
* var out = dtypesPoliciesEnvVars( funcData );
* // returns 'INPUT_DTYPES=\'numeric_and_generic\' OUTPUT_DTYPES=\'real_and_generic\' OUTPUT_POLICY=\'real_and_generic\' CASTING_POLICY=\'none\''
*/
function dtypesPoliciesEnvVars( funcData ) {
	return [
		'INPUT_DTYPES=\'' + funcData.input_dtypes + '\'',
		'OUTPUT_DTYPES=\'' + funcData.output_dtypes + '\'',
		'OUTPUT_POLICY=\'' + funcData.policies.output + '\'',
		'CASTING_POLICY=\'' + funcData.policies.casting + '\''
	].join( ' ' );
}


